use clap::{Arg, Command};
use crossterm::terminal::{enable_raw_mode, disable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen};
use crossterm::event::{self, Event, KeyCode, KeyModifiers};
use crossterm::execute;
use ratatui::prelude::*;
use ratatui::widgets::{Paragraph, Block, Borders};
use regex::Regex;
use std::io::{self, Read, IsTerminal, Write};
use std::collections::HashMap;
use std::time::{Instant, Duration};

// Define node
#[derive(Debug, Clone)]
struct Node {
    name: String,
    total: u64,
    own: u64,
    children: Vec<Node>,
}

impl Node {
    fn new(name: String) -> Self {
        Node { name, total: 0, own: 0, children: Vec::new() }
    }
    fn find_child_mut(&mut self, name: &str) -> Option<&mut Node> {
        self.children.iter_mut().find(|c| c.name == name)
    }
    fn sort_by_total(&mut self) {
        self.children.sort_by(|a,b| b.total.cmp(&a.total));
        for child in &mut self.children {
            child.sort_by_total();
        }
    }
}

// App view
#[derive(PartialEq, Clone, Copy)]
enum View {
    Flame,
    Top,
}
#[derive(PartialEq, Clone, Copy)]
enum TopSort {
    Total,
    Own,
}

struct App {
    raw: String,
    root: Node,
    display_name: String,
    total: u64,
    sorted: bool,
    debug: bool,
    echo: bool,
    view: View,
    // flame
    selected_path: Vec<usize>,
    zoom_path: Option<Vec<usize>>,
    flame_scroll: usize,
    // top
    top_selected: usize,
    top_scroll: usize,
    top_sort: TopSort,
    top_filter: Option<Regex>,
    top_filter_str: String,
    // search
    search_input: String,
    in_search: bool,
    search_regex: Option<Regex>,
    search_regex_str: String,
    search_matches: Vec<Vec<usize>>,
    search_idx: usize,
    info_msg: Option<String>,
    // timing
    build_time: Duration,
    // aggregated for top
    top_entries: Vec<(String, u64, u64)>, // name, total, own
}

impl App {
    fn get_node_by_path<'a>(&'a self, path: &[usize]) -> &'a Node {
        let mut node = &self.root;
        for &idx in path {
            node = &node.children[idx];
        }
        node
    }
    fn get_node_by_path_mut<'a>(&'a mut self, path: &[usize]) -> &'a mut Node {
        let mut node = &mut self.root;
        for &idx in path {
            node = &mut node.children[idx];
        }
        node
    }
    fn get_selected_node(&self) -> &Node {
        self.get_node_by_path(&self.selected_path)
    }
    fn get_zoom_node(&self) -> &Node {
        if let Some(p) = &self.zoom_path {
            self.get_node_by_path(p)
        } else {
            &self.root
        }
    }
