// helper to build tree
fn build_tree(raw: &str, sorted: bool) -> (Node, u64, Duration) {
    let start = Instant::now();
    let mut root = Node::new("all".to_string());
    let mut map: HashMap<String, (u64,u64)> = HashMap::new();
    let mut total_all = 0u64;
    for line in raw.lines() {
        if line.is_empty() {
            continue;
        }
        // find last space
        if let Some(idx) = line.rfind(' ') {
            let stack_part = &line[..idx];
            let count_part = &line[idx+1..];
            if count_part.is_empty() {
                continue;
            }
            // parse count
            let count_str = if count_part.starts_with('+') {
                &count_part[1..]
            } else if count_part.starts_with('-') {
                continue;
            } else {
                count_part
            };
            if count_str.is_empty() || !count_str.chars().all(|c| c.is_ascii_digit()) {
                continue;
            }
            let count: u64 = match count_str.parse() {
                Ok(v) => v,
                Err(_) => continue,
            };
            // split stack by ';'
            let frames: Vec<String> = stack_part.split(';').map(|s| s.to_string()).collect();
            // if frames is empty? but split will give at least one
            // update map for top aggregated
            // We'll also need to insert into tree
            // For top aggregated, we need per unique name totals
            // But we also need per-frame leaf own
            // We'll update map after tree? simpler to update map now
            // For each unique frame in this stack, we will later aggregate? But total for a name should be sum of counts for stacks containing that name anywhere, not just per occurrence count? However if same name appears multiple times in same stack (unlikely), should count once? In flame tree, name appears as node at specific depth, but top aggregated should sum total where name appears anywhere in stack (unique per stack). Our current frames may have duplicate names in same stack but different depths? e.g., "a;a 10" would have two a nodes at depths 1 and 2, but they are different nodes. For top, should we count "a" total as 10 once or twice? Probably once per stack, not per node depth. Our map approach counting per frame occurrence would double count if same name appears multiple times in same stack at different depths? But unlikely in real data. Simpler to count each frame occurrence: add count to each frame's total? But that would double count duplicate names in same stack. However typical stacks have unique names per level (no duplicate). We'll just add count to each frame name once per occurrence in frames list, but if duplicate name appears twice in same stack, it would add twice, which overcounts. However we can deduplicate per stack using HashSet.
            let mut seen = std::collections::HashSet::new();
            for f in &frames {
                if seen.insert(f.clone()) {
                    let e = map.entry(f.clone()).or_insert((0,0));
                    e.0 += count;
                }
            }
            // own for leaf
            if let Some(leaf) = frames.last() {
                let e = map.entry(leaf.clone()).or_insert((0,0));
                e.1 += count;
            }

            // Insert into tree
            total_all += count;
            root.total += count;
            let mut cur = &mut root;
            for (i, fr) in frames.iter().enumerate() {
                // find or create
                let idx = cur.children.iter().position(|c| &c.name == fr);
                let child_idx = if let Some(pos) = idx {
                    pos
                } else {
                    cur.children.push(Node::new(fr.clone()));
                    cur.children.len() - 1
                };
                cur = &mut cur.children[child_idx];
                cur.total += count;
                if i == frames.len() - 1 {
                    cur.own += count;
                }
            }
        } else {
            continue;
        }
    }
    if sorted {
        root.sort_by_total();
    }
    let dur = start.elapsed();
    (root, total_all, dur)
}

// color for flame
fn color_for(name: &str) -> Color {
    if name == "all" {
        return Color::Rgb(250,250,250);
    }
    // simple hash
    let mut hash: u32 = 0;
    for b in name.bytes() {
        hash = hash.wrapping_mul(31).wrapping_add(b as u32);
    }
    // generate warm palette
    let palette = [
        Color::Rgb(227,102,24),
        Color::Rgb(216,52,12),
        Color::Rgb(208,13,3),
        Color::Rgb(205,3,0),
        Color::Rgb(248,200,47),
        Color::Rgb(246,191,45),
        Color::Rgb(209,21,5),
        Color::Rgb(232,120,30),
        Color::Rgb(237,140,40),
    ];
    let idx = (hash as usize) % palette.len();
    palette[idx]
}

fn build_flame_rows(root: &Node, width: usize, zoom_path: &Option<Vec<usize>>) -> Vec<Vec<(String, usize, usize, Vec<usize>, u64)>> {
    // returns rows per depth, each entry: name, x_start, width, path, total
    let mut rows: Vec<Vec<(String, usize, usize, Vec<usize>, u64)>> = Vec::new();
    if let Some(zp) = zoom_path {
        let zoom_depth = zp.len();
        // ancestors up to zoom
        for d in 0..=zoom_depth {
            let path = zp[0..d].to_vec();
            let node = get_node_by_path_ref(root, &path);
            if rows.len() <= d {
                rows.push(Vec::new());
            }
            rows[d].push((node.name.clone(), 0, width, path.clone(), node.total));
        }
        // now expand zoomed subtree for deeper levels
        let zoom_node = get_node_by_path_ref(root, zp);
        // recursive helper
        fn recurse(node: &Node, x_start: usize, x_end: usize, depth: usize, rows: &mut Vec<Vec<(String,usize,usize,Vec<usize>,u64)>>, cur_path: Vec<usize>) {
            if node.children.is_empty() { return; }
            let parent_width = x_end - x_start;
            if node.total == 0 || parent_width == 0 { return; }
            let mut cur = x_start;
            for (i, child) in node.children.iter().enumerate() {
                let mut child_path = cur_path.clone();
                child_path.push(i);
                let child_width = if i == node.children.len()-1 {
                    x_end - cur
                } else {
                    let w = (child.total as f64 / node.total as f64 * parent_width as f64).round() as usize;
                    // ensure at least 1 if total>0
                    let w = if child.total>0 && w==0 {1} else {w};
                    // clamp to remaining
                    std::cmp::min(w, x_end - cur)
                };
                let child_x_start = cur;
                let child_x_end = cur + child_width;
                let child_depth = depth + 1;
                if rows.len() <= child_depth {
                    rows.resize(child_depth+1, Vec::new());
                }
                rows[child_depth].push((child.name.clone(), child_x_start, child_width, child_path.clone(), child.total));
                recurse(child, child_x_start, child_x_end, child_depth, rows, child_path);
                cur = child_x_end;
            }
        }
        recurse(zoom_node, 0, width, zoom_depth, &mut rows, zp.clone());
    } else {
        // no zoom, full
        fn recurse2(node: &Node, x_start: usize, x_end: usize, depth: usize, rows: &mut Vec<Vec<(String,usize,usize,Vec<usize>,u64)>>, cur_path: Vec<usize>) {
            if rows.len() <= depth {
                rows.resize(depth+1, Vec::new());
            }
            rows[depth].push((node.name.clone(), x_start, x_end - x_start, cur_path.clone(), node.total));
            if node.children.is_empty() { return; }
            let parent_width = x_end - x_start;
            if node.total == 0 || parent_width==0 { return; }
            let mut cur = x_start;
            for (i, child) in node.children.iter().enumerate() {
                let mut child_path = cur_path.clone();
                child_path.push(i);
                let child_width = if i == node.children.len()-1 {
                    x_end - cur
                } else {
                    let w = (child.total as f64 / node.total as f64 * parent_width as f64).round() as usize;
                    let w = if child.total>0 && w==0 {1} else {w};
                    std::cmp::min(w, x_end - cur)
                };
                let child_x_start = cur;
                let child_x_end = cur + child_width;
                recurse2(child, child_x_start, child_x_end, depth+1, rows, child_path);
                cur = child_x_end;
            }
        }
        recurse2(root, 0, width, 0, &mut rows, Vec::new());
    }
    rows
}

fn get_node_by_path_ref<'a>(root: &'a Node, path: &[usize]) -> &'a Node {
    let mut node = root;
    for &idx in path {
        node = &node.children[idx];
    }
    node
}

fn update_top_entries(app: &mut App) {
    // build aggregated map from tree
    let mut map: HashMap<String, (u64,u64)> = HashMap::new();
    fn traverse(node: &Node, map: &mut HashMap<String,(u64,u64)>) {
        if node.name != "all" {
            // For top, we need to aggregate by name? But node.total already per path. If same name appears in different branches, we need to sum.
            // We'll just add node's total/own to map entry for that name.
            // However this will double count if same name appears at multiple depths in same stack path? But then node.total includes counts from multiple stacks where name appears at that specific path, not globally. Summing across nodes with same name will give total samples where name appears at that path location, but if name appears in different branches, sum will be correct for unique samples? Might double count if name appears multiple times in same stack at different depths (rare).
            let e = map.entry(node.name.clone()).or_insert((0,0));
            e.0 += node.total;
            e.1 += node.own;
        }
        for child in &node.children {
            traverse(child, map);
        }
    }
    // Instead of traversing tree, we could use earlier map built during parsing but we don't have it now.
    // Let's traverse tree to build map
    for child in &app.root.children {
        traverse(child, &mut map);
    }
    let mut entries: Vec<(String,u64,u64)> = map.into_iter().map(|(k,(t,o))| (k,t,o)).collect();
    // apply filter if present
    if let Some(re) = &app.top_filter {
        entries.retain(|(name,_,_)| re.is_match(name));
    } else if let Some(re) = &app.search_regex {
        // also filter when search active? In top, filter is search
        entries.retain(|(name,_,_)| re.is_match(name));
    }
    // sorting
    match app.top_sort {
        TopSort::Total => entries.sort_by(|a,b| b.1.cmp(&a.1).then(b.2.cmp(&a.2))),
        TopSort::Own => entries.sort_by(|a,b| b.2.cmp(&a.2).then(b.1.cmp(&a.1))),
    }
    app.top_entries = entries;
    // clamp selection
    if app.top_entries.is_empty() {
        app.top_selected = 0;
    } else if app.top_selected >= app.top_entries.len() {
        app.top_selected = app.top_entries.len()-1;
    }
}

fn collect_search_matches(root: &Node, re: &Regex) -> Vec<Vec<usize>> {
    let mut matches = Vec::new();
    fn dfs(node: &Node, path: Vec<usize>, re: &Regex, out: &mut Vec<Vec<usize>>) {
        if re.is_match(&node.name) {
            out.push(path.clone());
        }
        for (i, child) in node.children.iter().enumerate() {
            let mut np = path.clone();
            np.push(i);
            dfs(child, np, re, out);
        }
    }
    // start from root children? Should we include root "all"? It contains "a" etc, but root name "all" may match regex "a". Should we include root? In our earlier search "a" matched a node total 20, not root. Root matching would also be 20 but same. Safer to include root as well but it will be first.
    dfs(root, Vec::new(), re, &mut matches);
    matches
}

RS
"}

