                        spans.push(Span::raw(before.to_string()));
                        if let Some(end) = remainder[start..].find(']') {
                            let inside = &remainder[start+1..start+end];
                            spans.push(Span::raw("[".to_string()));
                            spans.push(Span::styled(inside.to_string(), Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)));
                            spans.push(Span::raw("]".to_string()));
                            remainder = &remainder[start+end+1..];
                        } else {
                            break;
                        }
                    }
                    spans.push(Span::raw(remainder.to_string()));
                    Line::from(spans)
                };
                let inner = Layout::default().direction(Direction::Vertical).constraints([Constraint::Length(1), Constraint::Length(1)]).split(footer_area);
                f.render_widget(Paragraph::new(border_line), inner[0]);
                f.render_widget(Paragraph::new(help_with_style), inner[1]);
            }
        }).unwrap();

        app.render_time = render_start.elapsed();
        if first_render {
            first_render = false;
        }

        if event::poll(Duration::from_millis(50)).unwrap() {
            if let Event::Key(k) = event::read().unwrap() {
                if app.in_search {
                    match k.code {
                        KeyCode::Enter => {
                            let input = app.search_input.clone();
                            app.in_search = false;
                            app.search_input.clear();
                            if input.is_empty() {
                                app.info_msg = None;
                            } else {
                                match Regex::new(&input) {
                                    Ok(re) => {
                                        app.search_regex = Some(re.clone());
                                        app.search_regex_str = input.clone();
                                        app.search_matches = collect_matches(&app.root, &re);
                                        app.search_idx = 0;
                                        if app.search_matches.is_empty() {
                                            app.info_msg = None;
                                            // if no match, still set but will show 0?
                                        } else {
                                            // jump to first match?
                                            app.selected_path = app.search_matches[0].clone();
                                            // Ensure flame scroll shows selected
                                            // Need to adjust flame_scroll to contain selected depth
                                            let depth = app.selected_path.len();
                                            if depth < app.flame_scroll { app.flame_scroll = depth; }
                                            else if depth >= app.flame_scroll + (terminal.size().unwrap().height as usize - 7) { /* approximate */ }
                                            app.info_msg = None;
                                        }
                                        // For Top view, updating filter
                                        if app.view == View::Top {
                                            app.top_filter = Some(re);
                                            app.top_filter_str = input;
                                            update_top_entries(&mut app);
                                        }
                                    }
                                    Err(e) => {
                                        // show invalid regex info
                                        app.info_msg = Some(format!("Invalid regex: {}", e.to_string().split(':').last().unwrap_or(&input).trim()));
                                        // keep previous search? Original retains previous match after invalid? In probe6 invalid regex kept previous match "b".
                                        // We'll keep previous search_regex unchanged
                                    }
                                }
                            }
                        }
                        KeyCode::Esc => {
                            app.in_search = false;
                            app.search_input.clear();
                            // cancel search input, keep previous? Probably clear info?
                        }
                        KeyCode::Backspace => { app.search_input.pop(); }
                        KeyCode::Char(c) => {
                            // handle normal char, but need to consider modifiers?
                            if k.modifiers.contains(KeyModifiers::CONTROL) { /* ignore?*/ }
                            else {
                                app.search_input.push(c);
                            }
                        }
                        _ => {}
                    }
                } else {
                    match k.code {
                        KeyCode::Char('q') => { should_quit = true; }
                        KeyCode::Char('c') if k.modifiers.contains(KeyModifiers::CONTROL) => { should_quit = true; }
                        KeyCode::Char('h') | KeyCode::Left => {
                            // move left: if selected has sibling, move to previous sibling at same depth
                            if app.view == View::Flame {
                                if let Some(idx) = app.selected_path.last().cloned() {
                                    if idx > 0 {
                                        let parent_path = &app.selected_path[..app.selected_path.len()-1];
                                        let parent = app.get_node(parent_path);
                                        let prev_path = {
                                            let mut p = parent_path.to_vec();
                                            p.push(idx-1);
                                            p
                                        };
                                        // Need to ensure we move to sibling deepest? But we move to sibling at same depth.
                                        app.selected_path = prev_path;
                                    } else {
                                        // if at first sibling, maybe wrap? But original didn't wrap for h? In earlier test, h from b went to?? At b level, h went to? Actually test showed h from b after l to e went back to b. So h moves to previous sibling.
                                    }
                                } else {
                                    // at root, no move?
                                }
                            }
                        }
                        KeyCode::Char('l') | KeyCode::Right => {
                            if app.view == View::Flame {
                                if let Some(idx) = app.selected_path.last().cloned() {
                                    let parent_path = &app.selected_path[..app.selected_path.len()-1];
                                    let parent = app.get_node(parent_path);
                                    if idx +1 < parent.children.len() {
                                        let mut p = parent_path.to_vec();
                                        p.push(idx+1);
                                        app.selected_path = p;
                                    }
                                } else {
                                    // at root, move to first child? But l from b went to e (sibling). Need more precise.
                                    // For root "all" selected, l maybe does nothing (since only one root)
                                }
                            }
                        }
                        KeyCode::Char('j') | KeyCode::Down => {
                            if app.view == View::Flame {
                                let cur_depth = app.selected_path.len();
                                let cur_node = app.selected_node().clone();
                                if cur_node.children.is_empty() {
                                    // no child, maybe stay
                                } else {
                                    // move to first child
                                    let mut np = app.selected_path.clone();
                                    np.push(0);
                                    app.selected_path = np;
                                }
                                // need to ensure flame scroll includes new depth
                                let depth = app.selected_path.len();
                                // adjust scroll: if depth >= scroll + flame_h, scroll down
                                // we compute flame_h as visible rows approx terminal height - overhead
                                let h = terminal.size().unwrap().height as usize;
                                let visible = h.saturating_sub(7); // approx
                                if depth >= app.flame_scroll + visible {
                                    app.flame_scroll = depth - visible +1;
                                }
                            } else {
                                // Top
                                if !app.top_entries.is_empty() {
                                    if app.top_selected +1 < app.top_entries.len() {
                                        app.top_selected +=1;
                                        // scroll
                                        let h = terminal.size().unwrap().height as usize;
                                        let visible = h.saturating_sub(8);
                                        if app.top_selected >= app.top_scroll + visible {
                                            app.top_scroll = app.top_selected - visible +1;
                                        }
                                    }
                                }
                            }
                        }
                        KeyCode::Char('k') | KeyCode::Up => {
                            if app.view == View::Flame {
                                if !app.selected_path.is_empty() {
                                    app.selected_path.pop();
                                    let depth = app.selected_path.len();
                                    if depth < app.flame_scroll {
                                        app.flame_scroll = depth;
                                    }
                                }
                            } else {
                                if app.top_selected > 0 {
                                    app.top_selected -=1;
                                    if app.top_selected < app.top_scroll {
                                        app.top_scroll = app.top_selected;
                                    }
                                }
                            }
                        }
                        KeyCode::Char('f') => {
                            if app.view == View::Flame {
                                let total_depth = {
                                    let rows = build_rows(&app.root, terminal.size().unwrap().width as usize, &app.zoom_path);
                                    rows.len()
                                };
                                let h = terminal.size().unwrap().height as usize;
                                let visible = h.saturating_sub(7);
                                if app.flame_scroll + visible < total_depth {
                                    app.flame_scroll += visible;
                                    if app.flame_scroll + visible > total_depth {
                                        app.flame_scroll = total_depth.saturating_sub(visible);
                                    }
                                } else {
                                    // maybe max
                                }
                            } else {
                                // top scroll
                                let h = terminal.size().unwrap().height as usize;
                                let visible = h.saturating_sub(8);
                                if app.top_scroll + visible < app.top_entries.len() {
                                    app.top_scroll += 1; // original f scrolls by one page? For top, f maybe scroll down one page as well
                                    // but for flame deep we saw f jumps many lines (visible)
                                }
                                // Actually need to differentiate
                            }
                        }
                        KeyCode::Char('b') => {
                            if app.view == View::Flame {
                                if app.flame_scroll > 0 {
                                    let h = terminal.size().unwrap().height as usize;
                                    let visible = h.saturating_sub(7);
                                    if app.flame_scroll >= visible { app.flame_scroll -= visible; } else { app.flame_scroll =0; }
                                }
                            } else {
                                if app.top_scroll >0 { app.top_scroll -=1; }
                            }
                        }
                        KeyCode::Char('G') => {
                            if app.view == View::Flame {
                                let total_depth = {
                                    let rows = build_rows(&app.root, terminal.size().unwrap().width as usize, &app.zoom_path);
                                    rows.len()
                                };
                                let h = terminal.size().unwrap().height as usize;
                                let visible = h.saturating_sub(7);
                                app.flame_scroll = total_depth.saturating_sub(visible);
                                // also move selection to deepest? In earlier test, after G selected stayed? Actually after G with deep file, selected was f13 (mid) not deepest. So G only scrolls, not change selection.
                            } else {
                                // top: scroll to bottom
                                let h = terminal.size().unwrap().height as usize;
                                let visible = h.saturating_sub(8);
                                if app.top_entries.len() > visible {
                                    app.top_scroll = app.top_entries.len() - visible;
                                } else { app.top_scroll =0; }
                            }
                        }
                        KeyCode::Char('g') => {
                            if app.view == View::Flame {
                                app.flame_scroll = 0;
                            } else {
                                app.top_scroll =0;
                            }
                        }
                        KeyCode::Enter => {
                            if app.view == View::Flame {
                                // zoom in on selected
                                let sel = app.selected_path.clone();
                                if !sel.is_empty() {
                                    app.zoom_path = Some(sel.clone());
                                    // After zoom, selected remains? Original after Enter zoom, selected stayed same and scroll maybe reset? Let's keep.
                                    // Also flame_scroll maybe reset to 0? In original after zoom, flame rows show from top ancestors plus zoomed. For large zoom, maybe scroll is 0.
                                    app.flame_scroll =0;
                                } else {
                                    // if selected is all, zoom to all? Original zoom on all did nothing (stayed all). In probe11 after Enter on all, it stayed? Actually after Enter on all, selected still all and flame same. Zoom on all does nothing? We'll just keep zoom_path = Some([]) maybe?
                                }
                            }
                        }
                        KeyCode::Esc => {
                            // reset zoom
                            if app.zoom_path.is_some() {
                                app.zoom_path = None;
                                app.flame_scroll =0;
                            } else {
                                // if search active, maybe clear search? But Esc with search already handled via in_search.
                                // In flame, Esc resets zoom; if no zoom, maybe does nothing? But earlier Esc after search kept search? Actually after search Esc didn't clear.
                                // We'll keep.
                            }
                        }
                        KeyCode::Char('/') => {
                            app.in_search = true;
                            app.search_input.clear();
                            app.info_msg = None;
                        }
                        KeyCode::Char('#') => {
                            // search like cursor
                            let sel_name = app.selected_node().name.clone();
                            // escape regex special chars? Original uses "^name$" with exact match. For top, they also use that.
                            let pat = format!("^{}$", regex::escape(&sel_name));
                            match Regex::new(&pat) {
                                Ok(re) => {
                                    app.search_regex = Some(re);
                                    app.search_regex_str = pat.clone();
                                    app.search_matches = collect_matches(&app.root, &app.search_regex.as_ref().unwrap());
                                    app.search_idx = 0;
                                    if app.view == View::Top {
                                        app.top_filter = Some(app.search_regex.clone().unwrap());
                                        app.top_filter_str = pat;
                                        update_top_entries(&mut app);
                                    }
                                }
                                Err(_) => {}
                            }
                        }
                        KeyCode::Char('n') => {
                            if let Some(re) = &app.search_regex {
                                if !app.search_matches.is_empty() {
                                    app.search_idx = (app.search_idx + 1) % app.search_matches.len();
                                    app.selected_path = app.search_matches[app.search_idx].clone();
                                    // adjust scroll to show
                                    let depth = app.selected_path.len();
                                    let h = terminal.size().unwrap().height as usize;
                                    let visible = h.saturating_sub(7);
                                    if depth < app.flame_scroll { app.flame_scroll = depth; }
                                    else if depth >= app.flame_scroll + visible { app.flame_scroll = depth - visible +1; }
                                }
                            }
                        }
                        KeyCode::Char('N') => {
                            if let Some(re) = &app.search_regex {
                                if !app.search_matches.is_empty() {
                                    if app.search_idx == 0 { app.search_idx = app.search_matches.len()-1; } else { app.search_idx -=1; }
                                    app.selected_path = app.search_matches[app.search_idx].clone();
                                    let depth = app.selected_path.len();
                                    let h = terminal.size().unwrap().height as usize;
                                    let visible = h.saturating_sub(7);
                                    if depth < app.flame_scroll { app.flame_scroll = depth; }
                                    else if depth >= app.flame_scroll + visible { app.flame_scroll = depth - visible +1; }
                                }
                            }
                        }
                        KeyCode::Char('r') => {
                            // reset
                            app.selected_path = Vec::new();
                            app.zoom_path = None;
                            app.flame_scroll = 0;
                            app.search_regex = None;
                            app.search_regex_str.clear();
                            app.search_matches.clear();
                            app.search_idx = 0;
                            app.top_filter = None;
                            app.top_filter_str.clear();
                            app.top_selected = 0;
                            app.top_scroll = 0;
                            app.info_msg = None;
                            update_top_entries(&mut app);
                            app.view = View::Flame;
                        }
                        KeyCode::Tab => {
                            app.view = if app.view == View::Flame { View::Top } else { View::Flame };
                            // when switching, need to update top entries and maybe reset filter?
                            if app.view == View::Top { update_top_entries(&mut app); }
                        }
                        KeyCode::Char('1') => {
                            if app.view == View::Top {
                                app.top_sort = TopSort::Total;
                                update_top_entries(&mut app);
                            }
                        }
                        KeyCode::Char('2') => {
                            if app.view == View::Top {
                                app.top_sort = TopSort::Own;
                                update_top_entries(&mut app);
                            }
                        }
                        _ => {}
                    }
                }
            }
        }
    }

    disable_raw_mode().unwrap();
    execute!(terminal.backend_mut(), LeaveAlternateScreen).unwrap();
    terminal.show_cursor().unwrap();

    if app.echo {
        let mut out = io::stdout();
        if app.raw.is_empty() {
            writeln!(out).unwrap();
        } else {
            write!(out, "{}", app.raw).unwrap();
            writeln!(out).unwrap();
        }
        let _ = out.flush();
    }
    Ok(())
}
RS
"}

actions.command:
cat > src/main.rs <<'RS'
use clap::{Arg, Command};
use crossterm::{
    event::{self, Event, KeyCode, KeyModifiers},
    execute,
    terminal::{
        disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen,
    },
};
use ratatui::{
    layout::{Constraint, Direction, Layout},
    prelude::*,
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{Block, Borders, Paragraph},
};
use regex::Regex;
use std::{
    collections::{HashMap, HashSet},
    io::{self, IsTerminal, Read, Write},
    time::{Duration, Instant},
};

#[derive(Debug, Clone)]
struct Node {
    name: String,
    total: u64,
    own: u64,
    children: Vec<Node>,
}
impl Node {
    fn new(name: String) -> Self { Self { name, total: 0, own: 0, children: Vec::new() } }
    fn sort_by_total(&mut self) {
        self.children.sort_by(|a,b| b.total.cmp(&a.total));
        for c in &mut self.children { c.sort_by_total(); }
    }
}

#[derive(Clone, Copy, PartialEq)]
enum View { Flame, Top }
#[derive(Clone, Copy, PartialEq)]
enum TopSort { Total, Own }

struct App {
    raw: String,
    root: Node,
    total: u64,
    display_name: String,
    sorted: bool,
    debug: bool,
    echo: bool,
    view: View,
    selected_path: Vec<usize>,
    zoom_path: Option<Vec<usize>>,
    flame_scroll: usize,
    top_selected: usize,
    top_scroll: usize,
    top_sort: TopSort,
    top_filter: Option<Regex>,
    top_filter_str: String,
    in_search: bool,
    search_input: String,
    search_regex: Option<Regex>,
    search_regex_str: String,
    search_matches: Vec<Vec<usize>>,
    search_idx: usize,
    info_msg: Option<String>,
    build_time: Duration,
    render_time: Duration,
    top_entries: Vec<(String,u64,u64)>,
}

impl App {
    fn get_node(&self, path: &[usize]) -> &Node {
        let mut n = &self.root;
        for &i in path { n = &n.children[i]; }
        n
    }
    fn selected_node(&self) -> &Node { self.get_node(&self.selected_path) }
    fn zoom_node(&self) -> &Node {
        if let Some(p) = &self.zoom_path { self.get_node(p) } else { &self.root }
    }
}

fn get_node_ref<'a>(root: &'a Node, path: &[usize]) -> &'a Node {
    let mut n = root;
    for &i in path { n = &n.children[i]; }
    n
}

fn build_tree(raw: &str, sorted: bool) -> (Node, u64, Duration) {
    let start = Instant::now();
    let mut root = Node::new("all".to_string());
    let mut total_all = 0u64;
    for line in raw.lines() {
        if line.is_empty() { continue; }
        if let Some(idx) = line.rfind(' ') {
            let stack_part = &line[..idx];
            let count_part = &line[idx+1..];
            if count_part.is_empty() { continue; }
            let count_str = if count_part.starts_with('+') {
                &count_part[1..]
            } else if count_part.starts_with('-') {
                continue;
            } else {
                count_part
            };
            if count_str.is_empty() || !count_str.chars().all(|c| c.is_ascii_digit()) { continue; }
            let count: u64 = match count_str.parse() { Ok(v) => v, Err(_) => continue };
            let frames: Vec<String> = stack_part.split(';').map(|s| s.to_string()).collect();
            total_all += count;
            root.total += count;
            let mut cur = &mut root;
            for (i, fr) in frames.iter().enumerate() {
                let pos = cur.children.iter().position(|c| &c.name == fr);
                let idx = if let Some(p) = pos { p } else { cur.children.push(Node::new(fr.clone())); cur.children.len()-1 };
                cur = &mut cur.children[idx];
                cur.total += count;
                if i == frames.len()-1 { cur.own += count; }
            }
        }
    }
    if sorted { root.sort_by_total(); }
    let dur = start.elapsed();
    (root, total_all, dur)
}

fn update_top_entries(app: &mut App) {
    let mut map: HashMap<String, (u64,u64)> = HashMap::new();
    // collect via tree traversal aggregated per name summing node totals
    // But for duplicate names in same path we will double count; however to mimic original's per-stack unique, we would need raw data.
    // We have to deduce original's method: For "a;a 10", original top showed a total 10 (not 20) meaning it deduplicates per stack.
    // Our map via traversing tree would give 20 for "a;a". So we need to recompute map from raw data using per-stack unique method.
    // Let's rebuild map from raw
    let raw = app.raw.clone();
    for line in raw.lines() {
        if line.is_empty() { continue; }
        if let Some(idx) = line.rfind(' ') {
            let stack_part = &line[..idx];
            let count_part = &line[idx+1..];
            if count_part.is_empty() { continue; }
            let count_str = if count_part.starts_with('+') { &count_part[1..] } else if count_part.starts_with('-') { continue; } else { count_part };
            if count_str.is_empty() || !count_str.chars().all(|c| c.is_ascii_digit()) { continue; }
            let count: u64 = match count_str.parse() { Ok(v)=>v, Err(_)=>continue };
            let frames: Vec<String> = stack_part.split(';').map(|s| s.to_string()).collect();
            let mut seen: HashSet<String> = HashSet::new();
            for f in &frames {
                if seen.insert(f.clone()) {
                    let e = map.entry(f.clone()).or_insert((0,0));
                    e.0 += count;
                }
            }
            if let Some(leaf) = frames.last() {
                let e = map.entry(leaf.clone()).or_insert((0,0));
                e.1 += count;
            }
        }
    }
    let mut entries: Vec<(String,u64,u64)> = map.into_iter().map(|(k,(t,o))| (k,t,o)).collect();
    // filtering: if top_filter is set, or search_regex for Top? In Top view, filtering uses same search as Flame but as filter. Top filter is either top_filter or search_regex depending on context.
    // In Flame view, search is highlight; in Top view, search acts as filter.
    // From observations: When you press "/" in Flame and enter regex, it sets Match with that regex and keeps flame. In Top, pressing "/" filters entries.
    // They share same search state? The search matches in flame, but in top it filters list.
    // We'll treat top_filter as currently active filter string; if search is active but we are in Top, we filter.
    if app.view == View::Top {
        if let Some(re) = &app.top_filter {
            entries.retain(|(name,_,_)| re.is_match(name));
        } else if let Some(re) = &app.search_regex {
            entries.retain(|(name,_,_)| re.is_match(name));
        }
    }
    match app.top_sort {
        TopSort::Total => entries.sort_by(|a,b| b.1.cmp(&a.1).then(b.2.cmp(&a.2)).then(a.0.cmp(&b.0))),
        TopSort::Own => entries.sort_by(|a,b| b.2.cmp(&a.2).then(b.1.cmp(&a.1)).then(a.0.cmp(&b.0))),
    }
    app.top_entries = entries;
    if app.top_entries.is_empty() {
        app.top_selected = 0;
        app.top_scroll = 0;
    } else {
        if app.top_selected >= app.top_entries.len() {
            app.top_selected = app.top_entries.len()-1;
        }
        // adjust scroll so selected visible
        // will be handled elsewhere
    }
}

fn collect_matches(root: &Node, re: &Regex) -> Vec<Vec<usize>> {
    let mut out = Vec::new();
    fn dfs(node: &Node, path: Vec<usize>, re: &Regex, out: &mut Vec<Vec<usize>>) {
        if re.is_match(&node.name) {
            out.push(path.clone());
        }
        for (i, child) in node.children.iter().enumerate() {
            let mut np = path.clone(); np.push(i);
            dfs(child, np, re, out);
        }
    }
    dfs(root, Vec::new(), re, &mut out);
    out
}

fn color_for(name: &str) -> Color {
    if name == "all" { return Color::Rgb(250,250,250); }
    let mut h: u32 = 0;
    for b in name.bytes() { h = h.wrapping_mul(31).wrapping_add(b as u32); }
    let palette = [
        Color::Rgb(227,102,24),
        Color::Rgb(216,52,12),
        Color::Rgb(208,13,3),
        Color::Rgb(205,3,0),
        Color::Rgb(248,200,47),
        Color::Rgb(246,191,45),
        Color::Rgb(209,21,5),
        Color::Rgb(232,120,30),
        Color::Rgb(237,140,40),
        Color::Rgb(250,250,250),
        Color::Rgb(248,200,47),
    ];
    palette[(h as usize) % palette.len()]
}

fn build_rows(root: &Node, width: usize, zoom_path: &Option<Vec<usize>>) -> Vec<Vec<(String, usize, usize, Vec<usize>, u64)>> {
    let mut rows: Vec<Vec<(String, usize, usize, Vec<usize>, u64)>> = Vec::new();
    if let Some(zp) = zoom_path {
        let zoom_depth = zp.len();
        for d in 0..=zoom_depth {
            let path = zp[0..d].to_vec();
            let node = get_node_ref(root, &path);
            if rows.len() <= d { rows.push(Vec::new()); }
            rows[d].push((node.name.clone(), 0, width, path.clone(), node.total));
        }
        let zoom_node = get_node_ref(root, zp);
        fn rec(node: &Node, x0: usize, x1: usize, depth: usize, rows: &mut Vec<Vec<(String,usize,usize,Vec<usize>,u64)>>, cur_path: Vec<usize>) {
            if node.children.is_empty() { return; }
            let pw = x1 - x0;
            if node.total==0 || pw==0 { return; }
            let mut cur = x0;
            for (i, child) in node.children.iter().enumerate() {
                let mut np = cur_path.clone(); np.push(i);
                let cw = if i == node.children.len()-1 { x1 - cur } else {
                    let w = (child.total as f64 / node.total as f64 * pw as f64).round() as usize;
                    let w = if child.total>0 && w==0 {1} else {w};
                    std::cmp::min(w, x1-cur)
                };
                let cd = depth+1;
                if rows.len() <= cd { rows.resize(cd+1, Vec::new()); }
                rows[cd].push((child.name.clone(), cur, cw, np.clone(), child.total));
                rec(child, cur, cur+cw, cd, rows, np);
                cur += cw;
            }
        }
        rec(zoom_node, 0, width, zoom_depth, &mut rows, zp.clone());
    } else {
        fn rec2(node: &Node, x0: usize, x1: usize, depth: usize, rows: &mut Vec<Vec<(String,usize,usize,Vec<usize>,u64)>>, cur_path: Vec<usize>) {
            if rows.len() <= depth { rows.resize(depth+1, Vec::new()); }
            rows[depth].push((node.name.clone(), x0, x1-x0, cur_path.clone(), node.total));
            if node.children.is_empty() { return; }
            let pw = x1 - x0;
            if node.total==0 || pw==0 { return; }
            let mut cur = x0;
            for (i, child) in node.children.iter().enumerate() {
                let mut np = cur_path.clone(); np.push(i);
                let cw = if i == node.children.len()-1 { x1-cur } else {
                    let w = (child.total as f64 / node.total as f64 * pw as f64).round() as usize;
                    let w = if child.total>0 && w==0 {1} else {w};
                    std::cmp::min(w, x1-cur)
                };
                rec2(child, cur, cur+cw, depth+1, rows, np);
                cur+=cw;
            }
        }
        rec2(root, 0, width, 0, &mut rows, Vec::new());
    }
    rows
}

