                } else {
                    // Selected
                    let sel_title = format!("Selected {}", "─".repeat(width.saturating_sub(9)));
                    status_lines.push(Line::from(Span::styled(sel_title, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))));
                    let sel_node = app.selected_node();
                    let sel_total = sel_node.total;
                    let sel_pct = if app.total==0 { f64::NAN } else { sel_total as f64 / app.total as f64 *100.0 };
                    let sel_pct_str = if sel_pct.is_nan() { "NaN".to_string() } else { format!("{:.2}", sel_pct) };
                    let sel_line = if let Some(zp) = &app.zoom_path {
