    time::{Duration, Instant},
};

#[derive(Debug, Clone)]
struct Node {
    name: String,
    total: u64,
    own: u64,
    children: Vec<Node>,
}
impl Node {
    fn new(name: String) -> Self { Self { name, total: 0, own: 0, children: Vec::new() } }
    fn sort_by_total(&mut self) {
        self.children.sort_by(|a,b| b.total.cmp(&a.total));
        for c in &mut self.children { c.sort_by_total(); }
    }
}

#[derive(Clone, Copy, PartialEq)]
enum View { Flame, Top }
#[derive(Clone, Copy, PartialEq)]
enum TopSort { Total, Own }

struct App {
    raw: String,
    root: Node,
    total: u64,
    display_name: String,
    debug: bool,
    echo: bool,
    view: View,
    selected_path: Vec<usize>,
    zoom_path: Option<Vec<usize>>,
    flame_scroll: usize,
    top_selected: usize,
    top_scroll: usize,
    top_sort: TopSort,
    top_filter: Option<Regex>,
    top_filter_str: String,
    in_search: bool,
    search_input: String,
    search_regex: Option<Regex>,
    search_regex_str: String,
    search_matches: Vec<Vec<usize>>,
    search_idx: usize,
    info_msg: Option<String>,
    build_time: Duration,
    render_time: Duration,
    top_entries: Vec<(String,u64,u64)>,
}

fn get_node_ref<'a>(root: &'a Node, path: &[usize]) -> &'a Node {
    let mut n = root;
    for &i in path { n = &n.children[i]; }
    n
}

impl App {
    fn get_node(&self, path: &[usize]) -> &Node { get_node_ref(&self.root, path) }
    fn selected_node(&self) -> &Node { self.get_node(&self.selected_path) }
    fn zoom_node(&self) -> &Node {
        if let Some(p)=&self.zoom_path { self.get_node(p) } else { &self.root }
    }
}

fn build_tree(raw: &str, sorted: bool) -> (Node, u64, Duration) {
    let start = Instant::now();
    let mut root = Node::new("all".to_string());
    let mut total_all = 0u64;
    for line in raw.lines() {
        if line.is_empty() { continue; }
        if let Some(idx) = line.rfind(' ') {
            let stack_part = &line[..idx];
            let count_part = &line[idx+1..];
            if count_part.is_empty() { continue; }
            let count_str = if count_part.starts_with('+') { &count_part[1..] } else if count_part.starts_with('-') { continue; } else { count_part };
            if count_str.is_empty() || !count_str.chars().all(|c| c.is_ascii_digit()) { continue; }
            let count: u64 = match count_str.parse() { Ok(v)=>v, Err(_)=>continue };
            let frames: Vec<String> = stack_part.split(';').map(|s| s.to_string()).collect();
            total_all += count;
            root.total += count;
            let mut cur = &mut root;
            for (i, fr) in frames.iter().enumerate() {
                let pos = cur.children.iter().position(|c| &c.name == fr);
                let idx2 = if let Some(p)=pos { p } else { cur.children.push(Node::new(fr.clone())); cur.children.len()-1 };
                cur = &mut cur.children[idx2];
                cur.total += count;
                if i==frames.len()-1 { cur.own += count; }
            }
        }
    }
    if sorted { root.sort_by_total(); }
    (root, total_all, start.elapsed())
}

fn update_top_entries(app: &mut App) {
    let mut map: HashMap<String,(u64,u64)> = HashMap::new();
    for line in app.raw.lines() {
        if line.is_empty() { continue; }
        if let Some(idx)=line.rfind(' ') {
            let stack_part=&line[..idx];
            let count_part=&line[idx+1..];
            if count_part.is_empty() { continue; }
            let count_str = if count_part.starts_with('+') { &count_part[1..] } else if count_part.starts_with('-') { continue; } else { count_part };
            if count_str.is_empty() || !count_str.chars().all(|c| c.is_ascii_digit()) { continue; }
            let count: u64 = match count_str.parse() { Ok(v)=>v, Err(_)=>continue };
            let frames: Vec<String> = stack_part.split(';').map(|s| s.to_string()).collect();
            let mut seen: HashSet<String> = HashSet::new();
            for f in &frames {
                if seen.insert(f.clone()) {
                    let e = map.entry(f.clone()).or_insert((0,0));
                    e.0 += count;
                }
            }
            if let Some(leaf)=frames.last() {
                let e = map.entry(leaf.clone()).or_insert((0,0));
                e.1 += count;
            }
        }
    }
    let mut entries: Vec<(String,u64,u64)> = map.into_iter().map(|(k,(t,o))| (k,t,o)).collect();
    // apply filter
    if app.view == View::Top {
        if let Some(re)=&app.top_filter {
            entries.retain(|(n,_,_)| re.is_match(n));
        } else if let Some(re)=&app.search_regex {
            entries.retain(|(n,_,_)| re.is_match(n));
        }
    }
    match app.top_sort {
        TopSort::Total => entries.sort_by(|a,b| b.1.cmp(&a.1).then(b.2.cmp(&a.2))),
        TopSort::Own => entries.sort_by(|a,b| b.2.cmp(&a.2).then(b.1.cmp(&a.1))),
    }
    app.top_entries = entries;
    if app.top_entries.is_empty() { app.top_selected=0; app.top_scroll=0; }
    else if app.top_selected >= app.top_entries.len() { app.top_selected = app.top_entries.len()-1; }
}

fn collect_matches(root: &Node, re: &Regex) -> Vec<Vec<usize>> {
    let mut out=Vec::new();
    fn dfs(node: &Node, path: Vec<usize>, re: &Regex, out: &mut Vec<Vec<usize>>) {
        if re.is_match(&node.name) { out.push(path.clone()); }
        for (i, child) in node.children.iter().enumerate() {
            let mut np=path.clone(); np.push(i);
            dfs(child, np, re, out);
        }
    }
    dfs(root, Vec::new(), re, &mut out);
    out
}

fn color_for(name: &str) -> Color {
    if name=="all" { return Color::Rgb(250,250,250); }
    let mut h:u32=0;
    for b in name.bytes(){ h=h.wrapping_mul(31).wrapping_add(b as u32); }
    let palette = [
        Color::Rgb(227,102,24),
        Color::Rgb(216,52,12),
        Color::Rgb(208,13,3),
        Color::Rgb(205,3,0),
        Color::Rgb(248,200,47),
        Color::Rgb(246,191,45),
        Color::Rgb(209,21,5),
        Color::Rgb(232,120,30),
        Color::Rgb(237,140,40),
    ];
    palette[(h as usize)%palette.len()]
}

fn build_rows(root: &Node, width: usize, zoom_path: &Option<Vec<usize>>) -> Vec<Vec<(String,usize,usize,Vec<usize>,u64)>> {
    let mut rows: Vec<Vec<(String,usize,usize,Vec<usize>,u64)>> = Vec::new();
    if let Some(zp)=zoom_path {
        let zd=zp.len();
        for d in 0..=zd {
            let path=zp[0..d].to_vec();
            let node=get_node_ref(root,&path);
            if rows.len()<=d { rows.push(Vec::new()); }
            rows[d].push((node.name.clone(),0,width,path.clone(),node.total));
        }
        let zn=get_node_ref(root, zp);
        fn rec(node:&Node,x0:usize,x1:usize,depth:usize,rows:&mut Vec<Vec<(String,usize,usize,Vec<usize>,u64)>>,cur_path:Vec<usize>){
            if node.children.is_empty(){return;}
            let pw=x1-x0;
            if node.total==0||pw==0 {return;}
            let mut cur=x0;
            for (i,child) in node.children.iter().enumerate(){
                let mut np=cur_path.clone(); np.push(i);
                let cw= if i==node.children.len()-1 {x1-cur} else {
                    let w=(child.total as f64/node.total as f64*pw as f64).round() as usize;
                    let w=if child.total>0&&w==0 {1} else {w};
                    std::cmp::min(w,x1-cur)
                };
                let cd=depth+1;
                if rows.len()<=cd {rows.resize(cd+1,Vec::new());}
                rows[cd].push((child.name.clone(),cur,cw,np.clone(),child.total));
                rec(child,cur,cur+cw,cd,rows,np);
                cur+=cw;
            }
        }
        rec(zn,0,width,zd,&mut rows,zp.clone());
    } else {
        fn rec2(node:&Node,x0:usize,x1:usize,depth:usize,rows:&mut Vec<Vec<(String,usize,usize,Vec<usize>,u64)>>,cur_path:Vec<usize>){
            if rows.len()<=depth {rows.resize(depth+1,Vec::new());}
            rows[depth].push((node.name.clone(),x0,x1-x0,cur_path.clone(),node.total));
            if node.children.is_empty(){return;}
            let pw=x1-x0;
            if node.total==0||pw==0 {return;}
            let mut cur=x0;
            for (i,child) in node.children.iter().enumerate(){
                let mut np=cur_path.clone(); np.push(i);
                let cw= if i==node.children.len()-1 {x1-cur} else {
                    let w=(child.total as f64/node.total as f64*pw as f64).round() as usize;
                    let w=if child.total>0&&w==0 {1} else {w};
                    std::cmp::min(w,x1-cur)
                };
                rec2(child,cur,cur+cw,depth+1,rows,np);
                cur+=cw;
            }
        }
        rec2(root,0,width,0,&mut rows, Vec::new());
    }
    rows
}

fn main() -> io::Result<()> {
    let cmd = Command::new("flamelens").version("0.3.1").about("")
        .arg(Arg::new("FILENAME").help("Profile data filename").required(false))
        .arg(Arg::new("sorted").long("sorted").help("Whether to sort the stacks by time spent").action(clap::ArgAction::SetTrue))
        .arg(Arg::new("echo").long("echo").help("Print data to stdout on exit. Useful when piping to other tools").action(clap::ArgAction::SetTrue))
        .arg(Arg::new("debug").long("debug").help("Show debug info").action(clap::ArgAction::SetTrue));
    let matches = cmd.get_matches();
    let filename: Option<String> = matches.get_one::<String>("FILENAME").cloned();
    let sorted = matches.get_flag("sorted");
    let echo = matches.get_flag("echo");
    let debug = matches.get_flag("debug");

    let (raw, display_name) = if let Some(fname)=filename {
        let data = std::fs::read_to_string(&fname).unwrap_or_else(|e| panic!("Could not read file: {:?}", e));
        (data, fname)
    } else {
        let mut s = String::new();
        if io::stdin().is_terminal() {
            (String::new(), "stdin".to_string())
        } else {
            let _ = io::stdin().read_to_string(&mut s);
            (s, "stdin".to_string())
        }
    };
    let (root,total,build_time)=build_tree(&raw, sorted);
    let mut app = App {
        raw: raw.clone(),
        root,
        total,
        display_name,
        debug,
        echo,
        view: View::Flame,
        selected_path: Vec::new(),
        zoom_path: None,
        flame_scroll: 0,
        top_selected: 0,
        top_scroll: 0,
        top_sort: TopSort::Own,
        top_filter: None,
        top_filter_str: String::new(),
        in_search: false,
        search_input: String::new(),
        search_regex: None,
        search_regex_str: String::new(),
        search_matches: Vec::new(),
        search_idx: 0,
        info_msg: None,
        build_time,
        render_time: Duration::from_millis(0),
        top_entries: Vec::new(),
    };
    update_top_entries(&mut app);

    let mut stdout = io::stdout();
    if let Err(_) = enable_raw_mode() {
        eprintln!("Error: Os {{ code: 11, kind: WouldBlock, message: \"Resource temporarily unavailable\" }}");
        if app.echo {
            if app.raw.is_empty() { writeln!(stdout).unwrap(); } else { write!(stdout,"{}",app.raw).unwrap(); writeln!(stdout).unwrap(); }
            let _ = stdout.flush();
        }
        std::process::exit(1);
    }
    execute!(stdout, EnterAlternateScreen).unwrap();
    let backend = ratatui::backend::CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend).unwrap();
    let mut should_quit = false;
    while !should_quit {
        let render_start = Instant::now();
        terminal.draw(|f| {
            let area = f.area();
            let width = area.width as usize;
            // header title
            let header_line_with_style = {
                let left = if app.view==View::Flame { " [Flamegraph] | Top" } else { " Flamegraph | [Top]" };
                let center = &app.display_name;
                let right = "flamelens v0.3.1";
                let remaining = width.saturating_sub(left.len()+center.len()+right.len());
                let left_pad = if remaining>=1 { remaining/2+1 } else {0};
                let right_pad = remaining.saturating_sub(left_pad);
                let mut spans=Vec::new();
                if app.view==View::Flame {
                    spans.push(Span::styled(" [Flamegraph]", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)));
                    spans.push(Span::raw(" | Top"));
                } else {
                    spans.push(Span::raw(" Flamegraph | "));
                    spans.push(Span::styled("[Top]", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)));
                }
                spans.push(Span::raw(" ".repeat(left_pad)));
                spans.push(Span::styled(center.clone(), Style::default().add_modifier(Modifier::BOLD)));
                spans.push(Span::raw(" ".repeat(right_pad)));
                spans.push(Span::styled(right, Style::default().add_modifier(Modifier::BOLD)));
                Line::from(spans)
            };
            // compute status lines height
            let mut status_h = 2; // Selected border+line
            if app.in_search {
                status_h = 2;
            } else {
                if app.search_regex.is_some() { status_h += 2; }
                if app.info_msg.is_some() { status_h += 2; }
                if app.debug { status_h += 2; }
            }
            let top_h = if app.view==View::Top { 1 } else { 0 }; // top header inside flame area? Actually for Top, header is inside main area
            // flame_h
            let avail_h = area.height as usize;
            let header_h = 3;
            let footer_h = 2;
            let flame_h = avail_h.saturating_sub(header_h + status_h + footer_h);
            // For Top view, flame_h includes top table header row? We'll handle inside.
            let chunks = Layout::default().direction(Direction::Vertical).constraints([
                Constraint::Length(3), Constraint::Length(flame_h as u16), Constraint::Length(status_h as u16), Constraint::Length(2)
            ]).split(area);
            // header
            {
                let inner = Layout::default().direction(Direction::Vertical).constraints([Constraint::Length(1),Constraint::Length(1),Constraint::Length(1)]).split(chunks[0]);
                let border = "─".repeat(width);
                f.render_widget(Paragraph::new(border.clone()), inner[0]);
                f.render_widget(Paragraph::new(header_line_with_style), inner[1]);
                f.render_widget(Paragraph::new(border.clone()), inner[2]);
            }
            // main area
            if app.view==View::Flame {
                let flame_area = chunks[1];
                let rows = build_rows(&app.root, width, &app.zoom_path);
                let total_depth = rows.len();
                // ensure scroll
                let visible = flame_h;
                let start = app.flame_scroll.min(total_depth.saturating_sub(1));
                let mut lines_vec: Vec<Line> = Vec::new();
                for depth in start..(start+visible).min(total_depth) {
                    let entries = &rows[depth];
                    let mut sorted = entries.clone();
                    sorted.sort_by_key(|e| e.1);
                    let mut spans: Vec<Span>=Vec::new();
                    let mut cur_x=0usize;
                    for (name,x,w,path,_) in sorted {
                        if x > cur_x { spans.push(Span::raw(" ".repeat(x-cur_x))); cur_x=x; }
                        let is_match = if let Some(re)=&app.search_regex { re.is_match(&name) } else { false };
                        let mut style = Style::default().bg(color_for(&name)).fg(Color::Rgb(225,225,225));
                        if name=="all" { style = style.fg(Color::Rgb(10,10,10)); }
                        if is_match {
                            style = Style::default().bg(Color::Rgb(10,35,150)).fg(Color::Rgb(225,225,225));
                            // We'll highlight matched name with bold red inner? To mimic original, we need to split name char coloring? Original had red for the matched substring? Actually it highlighted the entire block blue, but the text "b" was bright red bold inside blue. Let's for simplicity make whole block blue with white text? But need red?
                            // We'll make bg blue, fg white but also bold for matched?
                            style = style.add_modifier(Modifier::BOLD);
                        }
                        let display = if name.len() > w { name[..w].to_string() } else { format!(" {}{}", name, " ".repeat(w - name.len() -1)) };
                        // Ensure leading space for " all" type: our display adds leading space, but name "all" already is "all", we add " all" with leading space. For width w, we need to pad after.
                        // If we do format!(" {}{}", name, ...), we get leading space. For w=80, name="all" len3, w=80 => display = " all"+77 spaces = 80 total, matches original " all" padded.
                        // For w smaller, e.g., w=1, name.len() > w? Then truncate would lose leading space? But we handle.
                        // For match, we need to keep background full width, so display should be length w.
                        let display = if name.len()+1 > w {
                            // need to truncate with leading space? original flame first line " all" even for width 80 has leading space. So we should ensure display starts with space.
                            let mut s = format!(" {}", name);
                            if s.len() > w { s[..w].to_string() } else { s }
                        } else {
                            format!(" {}{}", name, " ".repeat(w - name.len() -1))
                        };
                        // For "all" with width large, display " all" + spaces.
                        spans.push(Span::styled(display, style));
                        cur_x+=w;
                    }
                    if cur_x < width { spans.push(Span::raw(" ".repeat(width-cur_x))); }
                    lines_vec.push(Line::from(spans));
                }
                while lines_vec.len() < flame_h { lines_vec.push(Line::from("")); }
                f.render_widget(Paragraph::new(lines_vec), flame_area);
            } else {
                // Top
                let top_area = chunks[1];
                let mut lines: Vec<Line> = Vec::new();
                let header_str = if app.top_sort==TopSort::Total {
                    // "Total [▼]     Own         Name"
                    // Need exact spacing: original had "Total [▼]     Own         Name" for Total sorted.
                    // Let's compute exact: For width 80, header length? Original capture for top after sorting by total (press 1) was "Total [▼]     Own         Name"
                    // For default (Own sorted) was "Total          Own [▼]       Name"
                    // We need to replicate spacing to match 80 width? Actually header is left-aligned, not full width. Let's just use those strings verbatim.
                    "Total [▼]     Own         Name"
                } else {
                    "Total          Own [▼]       Name"
                };
                lines.push(Line::from(header_str));
                let visible = flame_h.saturating_sub(1);
                let start = app.top_scroll.min(app.top_entries.len().saturating_sub(1));
                let end = (start+visible).min(app.top_entries.len());
                for idx in start..end {
                    let (name,total,own)=&app.top_entries[idx];
                    let total_pct = if app.total==0 { f64::NAN } else { *total as f64 / app.total as f64 *100.0 };
                    let own_pct = if app.total==0 { f64::NAN } else { *own as f64 / app.total as f64 *100.0 };
                    let total_str = if total_pct.is_nan() { format!("{} (NaN%)", total)} else { format!("{} ({:.2}%)", total, total_pct)};
                    let own_str = if own_pct.is_nan() { format!("{} (NaN%)", own)} else { format!("{} ({:.2}%)", own, own_pct)};
                    let line_str = format!("{:<14}{:<12}{}", total_str, own_str, name);
                    let style = if idx==app.top_selected { Style::default().bg(Color::White).fg(Color::Black) } else { Style::default() };
                    lines.push(Line::from(Span::styled(line_str, style)));
                }
                while lines.len() < flame_h { lines.push(Line::from("")); }
                f.render_widget(Paragraph::new(lines), top_area);
            }
            // status
            {
                let status_area = chunks[2];
                let mut lines: Vec<Line>=Vec::new();
                if app.in_search {
                    let border = format!("Search {}", "─".repeat(width.saturating_sub(7)));
                    lines.push(Line::from(Span::styled(border, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))));
                    lines.push(Line::from(app.search_input.clone()));
                } else {
                    // In Flame, status includes Selected and possibly Match, Info, Debug
                    // In Top, status includes Match and Info, but not Selected? Actually Top's Selected is not shown; instead top table selection is highlighted, but status still shows Match/Info?
                    // From captures: Flame always shows Selected. Top does NOT show Selected; it shows only header table and maybe Match, but not Selected.
                    // Let's check: For Top view, capture did not have Selected line, only table. But when we had flame->tab->top, the bottom status for top did not have Selected line, just border and help? Actually capture for top had no Selected, but after searching in Top, it showed Match. So we need to differentiate.
                    if app.view==View::Flame {
                        // Selected
                        let sel_title = format!("Selected {}", "─".repeat(width.saturating_sub(9)));
                        lines.push(Line::from(Span::styled(sel_title, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))));
                        let sel_node = app.selected_node();
                        let sel_total = sel_node.total;
                        let sel_pct = if app.total==0 { f64::NAN } else { sel_total as f64 / app.total as f64 *100.0 };
                        let sel_pct_str = if sel_pct.is_nan() { "NaN".to_string()} else { format!("{:.2}", sel_pct)};
                        let sel_line = if let Some(_) = &app.zoom_path {
                            let zoom_total = app.zoom_node().total;
                            let zoom_pct = if zoom_total==0 { f64::NAN } else { sel_total as f64 / zoom_total as f64 *100.0 };
                            let zoom_pct_str = if zoom_pct.is_nan() { "NaN".to_string()} else { format!("{:.2}", zoom_pct)};
                            format!("{} [{} samples, {}% of all, {}% of zoomed]", sel_node.name, sel_total, sel_pct_str, zoom_pct_str)
                        } else {
                            format!("{} [{} samples, {}% of all]", sel_node.name, sel_total, sel_pct_str)
                        };
                        lines.push(Line::from(sel_line));
                        if let Some(re)=&app.search_regex {
                            let match_title = format!("Match {}", "─".repeat(width.saturating_sub(6)));
                            lines.push(Line::from(Span::styled(match_title, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))));
                            // compute matched total via per-stack unique
                            let mut matched_total_alt=0u64;
                            for line in app.raw.lines() {
                                if line.is_empty(){continue;}
                                if let Some(idx)=line.rfind(' ') {
                                    let stack_part=&line[..idx];
                                    let count_part=&line[idx+1..];
                                    if count_part.is_empty(){continue;}
                                    let count_str= if count_part.starts_with('+') {&count_part[1..]} else if count_part.starts_with('-'){continue;} else {count_part};
                                    if count_str.is_empty()||!count_str.chars().all(|c| c.is_ascii_digit()){continue;}
                                    let count:u64=match count_str.parse(){Ok(v)=>v,Err(_)=>continue};
                                    let frames:Vec<&str>=stack_part.split(';').collect();
                                    if frames.iter().any(|f| re.is_match(f)) { matched_total_alt+=count; }
                                }
                            }
                            let matched_pct = if app.total==0 {f64::NAN} else {matched_total_alt as f64/app.total as f64*100.0};
                            let matched_pct_str = if matched_pct.is_nan(){"NaN".to_string()}else{format!("{:.2}",matched_pct)};
                            let val = if app.search_matches.is_empty() {
                                format!("\"{}\" [0 samples, 0.00% of all] (no match; showing all)", app.search_regex_str)
                            } else {
                                if app.zoom_path.is_some() {
                                    let zoom_total=app.zoom_node().total;
                                    let zoom_pct= if zoom_total==0 {f64::NAN} else {matched_total_alt as f64/zoom_total as f64*100.0};
                                    let zoom_pct_str= if zoom_pct.is_nan(){"NaN".to_string()}else{format!("{:.2}",zoom_pct)};
                                    format!("\"{}\" [{} samples, {}% of all, {}% of zoomed]",app.search_regex_str,matched_total_alt,matched_pct_str,zoom_pct_str)
                                } else {
                                    format!("\"{}\" [{} samples, {}% of all]",app.search_regex_str,matched_total_alt,matched_pct_str)
                                }
                            };
                            lines.push(Line::from(val));
                        }
                        if let Some(msg)=&app.info_msg {
                            let info_title = format!("Info {}", "─".repeat(width.saturating_sub(5)));
                            lines.push(Line::from(Span::styled(info_title, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))));
                            lines.push(Line::from(msg.clone()));
                        }
                        if app.debug {
                            let debug_title = format!("Debug {}", "─".repeat(width.saturating_sub(6)));
                            lines.push(Line::from(Span::styled(debug_title, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))));
                            let dbg_line = format!("Debug: flamegraph:{:.2}ms render:{:.2}ms", app.build_time.as_secs_f64()*1000.0, app.render_time.as_secs_f64()*1000.0);
                            lines.push(Line::from(dbg_line));
                        }
                    } else {
                        // Top view status: only Match and Info and Debug? But also maybe need to show Match even in Top after search.
                        if let Some(re)=&app.search_regex {
                            let match_title = format!("Match {}", "─".repeat(width.saturating_sub(6)));
                            lines.push(Line::from(Span::styled(match_title, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))));
                            let mut matched_total_alt=0u64;
                            for line in app.raw.lines() {
                                if line.is_empty(){continue;}
                                if let Some(idx)=line.rfind(' ') {
                                    let stack_part=&line[..idx];
                                    let count_part=&line[idx+1..];
                                    if count_part.is_empty(){continue;}
                                    let count_str= if count_part.starts_with('+') {&count_part[1..]} else if count_part.starts_with('-'){continue;} else {count_part};
                                    if count_str.is_empty()||!count_str.chars().all(|c| c.is_ascii_digit()){continue;}
                                    let count:u64=match count_str.parse(){Ok(v)=>v,Err(_)=>continue};
                                    let frames:Vec<&str>=stack_part.split(';').collect();
                                    if frames.iter().any(|f| re.is_match(f)) { matched_total_alt+=count; }
                                }
                            }
                            let matched_pct = if app.total==0 {f64::NAN} else {matched_total_alt as f64/app.total as f64*100.0};
                            let matched_pct_str = if matched_pct.is_nan(){"NaN".to_string()}else{format!("{:.2}",matched_pct)};
                            let val = if app.search_matches.is_empty() {
                                format!("\"{}\" [0 samples, 0.00% of all] (no match; showing all)", app.search_regex_str)
                            } else {
                                format!("\"{}\" [{} samples, {}% of all]", app.search_regex_str, matched_total_alt, matched_pct_str)
                            };
                            lines.push(Line::from(val));
                        } else {
                            // No match, but maybe we need to fill with empty? For top without search, status area should be zero? But our status_h was 2 for Flame; for Top without search and no debug, what is status_h? In captures, Top without search had 0 status lines (just header table and then border). Actually capture for Top 80x24 had: after table lines, directly border and help, no Selected. So status_h for Top without search should be 0, but we set to 2 earlier.
                            // For Top, we should have status_h = 0 + (search?2) + (info?2) + (debug?2)
                            // Our earlier calc used same status_h for both views, but for Top it should be less.
                            // We'll handle by not pushing Selected for Top.
                        }
                        if let Some(msg)=&app.info_msg {
                            let info_title = format!("Info {}", "─".repeat(width.saturating_sub(5)));
                            lines.push(Line::from(Span::styled(info_title, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))));
                            lines.push(Line::from(msg.clone()));
                        }
                        if app.debug {
                            let debug_title = format!("Debug {}", "─".repeat(width.saturating_sub(6)));
                            lines.push(Line::from(Span::styled(debug_title, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))));
                            let dbg_line = format!("Debug: flamegraph:{:.2}ms render:{:.2}ms", app.build_time.as_secs_f64()*1000.0, app.render_time.as_secs_f64()*1000.0);
                            lines.push(Line::from(dbg_line));
                        }
                        // If Top and no status lines needed, we need to ensure lines is empty but status_area height may be 0? However our status_h calculation assumed 2 for Flame only. For Top, we recalculated status_h correctly now as variable.
                        // But we already computed status_h before drawing; for Top with no search, it will be 0 + maybe debug. So chunks[2] height is that.
                        // So if Top has no status, chunks[2] will be 0 height and we render nothing.
                    }
                }
                while lines.len() < status_area.height as usize {
                    lines.push(Line::from(""));
                }
                f.render_widget(Paragraph::new(lines), status_area);
            }
            // footer
            {
                let footer_area = chunks[3];
                let inner = Layout::default().direction(Direction::Vertical).constraints([Constraint::Length(1),Constraint::Length(1)]).split(footer_area);
                let border = "─".repeat(width);
                f.render_widget(Paragraph::new(border.clone()), inner[0]);
                let help_line = if app.view==View::Flame {
                    if app.search_regex.is_some() {
                        " [hjkl: move cursor] [f/b: scroll] [enter/esc: zoom] [/: search] [#: search like cursor] [n/N: next/prev search] [r: reset] [tab: switch view] [q: quit]"
                    } else {
                        " [hjkl: move cursor] [f/b: scroll] [enter/esc: zoom] [/: search] [#: search like cursor] [r: reset] [tab: switch view] [q: quit]"
                    }
                } else {
                    " [j/k: move cursor] [f/b: scroll] [1: sort by total] [2: sort by own] [/: filter] [r: reset] [tab: switch view] [q: quit]"
                };
                let mut spans=Vec::new();
                let mut rem = help_line;
                while let Some(s)=rem.find('[') {
                    spans.push(Span::raw(rem[..s].to_string()));
                    if let Some(e)=rem[s..].find(']') {
                        let inside=&rem[s+1..s+e];
                        spans.push(Span::raw("[".to_string()));
                        spans.push(Span::styled(inside.to_string(), Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)));
                        spans.push(Span::raw("]".to_string()));
                        rem=&rem[s+e+1..];
                    } else { break; }
                }
                spans.push(Span::raw(rem.to_string()));
                f.render_widget(Paragraph::new(Line::from(spans)), inner[1]);
            }
        }).unwrap();
        app.render_time = render_start.elapsed();
        if event::poll(Duration::from_millis(50)).unwrap() {
            if let Event::Key(k)=event::read().unwrap() {
                if app.in_search {
                    match k.code {
                        KeyCode::Enter => {
                            let input=app.search_input.clone();
                            app.in_search=false;
                            app.search_input.clear();
                            if input.is_empty() { app.info_msg=None; }
                            else {
                                match Regex::new(&input) {
                                    Ok(re) => {
                                        app.search_regex=Some(re.clone());
                                        app.search_regex_str=input.clone();
                                        app.search_matches=collect_matches(&app.root,&re);
                                        app.search_idx=0;
                                        if !app.search_matches.is_empty() {
                                            app.selected_path=app.search_matches[0].clone();
                                            let depth=app.selected_path.len();
                                            let h=terminal.size().unwrap().height as usize;
                                            let visible=h.saturating_sub(7);
                                            if depth < app.flame_scroll { app.flame_scroll=depth; }
                                            else if depth >= app.flame_scroll+visible { app.flame_scroll=depth - visible +1; }
                                            app.info_msg=None;
                                        }
                                        if app.view==View::Top {
                                            app.top_filter=Some(re);
                                            app.top_filter_str=input;
                                            update_top_entries(&mut app);
                                        }
                                    }
                                    Err(e) => {
                                        // extract short message
                                        let msg = e.to_string();
                                        // original shows "Invalid regex: [" for pattern "["
                                        // We'll show last part after ':'
                                        let short = msg.split(':').last().unwrap_or(&input).trim().to_string();
                                        // But for "[" pattern, msg is "regex parse error:\n    [\n    ^\nerror: unclosed character class"
                                        // Original shows "Invalid regex: ["
                                        // So we can just show "Invalid regex: {}" with input as given
                                        app.info_msg=Some(format!("Invalid regex: {}", input));
                                        // keep previous search_regex?
                                    }
                                }
                            }
                        }
                        KeyCode::Esc => { app.in_search=false; app.search_input.clear(); }
                        KeyCode::Backspace => { app.search_input.pop(); }
                        KeyCode::Char(c) => {
                            if !k.modifiers.contains(KeyModifiers::CONTROL) {
                                app.search_input.push(c);
                            }
                        }
                        _=>{}
                    }
                } else {
                    match k.code {
                        KeyCode::Char('q') => { should_quit=true; }
                        KeyCode::Char('c') if k.modifiers.contains(KeyModifiers::CONTROL) => { should_quit=true; }
                        KeyCode::Char('h') | KeyCode::Left => {
                            if app.view==View::Flame {
                                if let Some(idx)=app.selected_path.last().cloned() {
                                    let parent_path=&app.selected_path[..app.selected_path.len()-1];
                                    if idx>0 {
                                        let mut p=parent_path.to_vec(); p.push(idx-1);
                                        app.selected_path=p;
                                    }
                                }
                            }
                        }
                        KeyCode::Char('l') | KeyCode::Right => {
                            if app.view==View::Flame {
                                if let Some(idx)=app.selected_path.last().cloned() {
                                    let parent_path=&app.selected_path[..app.selected_path.len()-1];
                                    let parent=app.get_node(parent_path);
                                    if idx+1 < parent.children.len() {
                                        let mut p=parent_path.to_vec(); p.push(idx+1);
                                        app.selected_path=p;
                                    }
                                }
                            }
                        }
                        KeyCode::Char('j') | KeyCode::Down => {
                            if app.view==View::Flame {
                                let cur = app.selected_node().clone();
                                if !cur.children.is_empty() {
                                    let mut np=app.selected_path.clone(); np.push(0);
                                    app.selected_path=np;
                                    let depth=app.selected_path.len();
                                    let h=terminal.size().unwrap().height as usize;
                                    let visible=h.saturating_sub(7);
                                    if depth >= app.flame_scroll+visible { app.flame_scroll=depth - visible +1; }
                                }
                            } else {
                                if !app.top_entries.is_empty() && app.top_selected+1 < app.top_entries.len() {
                                    app.top_selected+=1;
                                    let h=terminal.size().unwrap().height as usize;
                                    let visible=h.saturating_sub(8);
                                    if app.top_selected >= app.top_scroll+visible { app.top_scroll=app.top_selected - visible +1; }
                                }
                            }
                        }
                        KeyCode::Char('k') | KeyCode::Up => {
                            if app.view==View::Flame {
                                if !app.selected_path.is_empty() {
                                    app.selected_path.pop();
                                    let depth=app.selected_path.len();
                                    if depth < app.flame_scroll { app.flame_scroll=depth; }
                                }
                            } else {
                                if app.top_selected>0 {
                                    app.top_selected-=1;
                                    if app.top_selected < app.top_scroll { app.top_scroll=app.top_selected; }
                                }
                            }
                        }
                        KeyCode::Char('f') => {
                            if app.view==View::Flame {
                                let rows=build_rows(&app.root, terminal.size().unwrap().width as usize, &app.zoom_path);
                                let total_depth=rows.len();
                                let h=terminal.size().unwrap().height as usize;
                                let visible=h.saturating_sub(7);
                                if app.flame_scroll+visible < total_depth {
                                    app.flame_scroll+=visible;
                                    if app.flame_scroll+visible > total_depth { app.flame_scroll=total_depth.saturating_sub(visible); }
                                }
                            } else {
                                let h=terminal.size().unwrap().height as usize;
                                let visible=h.saturating_sub(8);
                                if app.top_scroll+visible < app.top_entries.len() { app.top_scroll+=1; }
                            }
                        }
                        KeyCode::Char('b') => {
                            if app.view==View::Flame {
                                if app.flame_scroll>0 {
                                    let h=terminal.size().unwrap().height as usize;
                                    let visible=h.saturating_sub(7);
                                    if app.flame_scroll>=visible { app.flame_scroll-=visible; } else { app.flame_scroll=0; }
                                }
                            } else {
                                if app.top_scroll>0 { app.top_scroll-=1; }
                            }
                        }
                        KeyCode::Char('G') => {
                            if app.view==View::Flame {
                                let rows=build_rows(&app.root, terminal.size().unwrap().width as usize, &app.zoom_path);
                                let total_depth=rows.len();
                                let h=terminal.size().unwrap().height as usize;
                                let visible=h.saturating_sub(7);
                                app.flame_scroll=total_depth.saturating_sub(visible);
                            } else {
                                let h=terminal.size().unwrap().height as usize;
                                let visible=h.saturating_sub(8);
                                if app.top_entries.len()>visible { app.top_scroll=app.top_entries.len()-visible; } else { app.top_scroll=0; }
                            }
                        }
                        KeyCode::Char('g') => {
                            if app.view==View::Flame { app.flame_scroll=0; } else { app.top_scroll=0; }
                        }
                        KeyCode::Enter => {
                            if app.view==View::Flame {
                                let sel=app.selected_path.clone();
                                if !sel.is_empty() {
                                    app.zoom_path=Some(sel);
                                    app.flame_scroll=0;
                                }
                            }
                        }
                        KeyCode::Esc => {
                            if app.zoom_path.is_some() { app.zoom_path=None; app.flame_scroll=0; }
                        }
                        KeyCode::Char('/') => { app.in_search=true; app.search_input.clear(); app.info_msg=None; }
                        KeyCode::Char('#') => {
                            let sel_name=app.selected_node().name.clone();
                            let pat=format!("^{}$", regex::escape(&sel_name));
                            if let Ok(re)=Regex::new(&pat){
                                app.search_regex=Some(re.clone());
                                app.search_regex_str=pat.clone();
                                app.search_matches=collect_matches(&app.root,&re);
                                app.search_idx=0;
                                if app.view==View::Top {
                                    app.top_filter=Some(re);
                                    app.top_filter_str=pat;
                                    update_top_entries(&mut app);
                                }
                            }
                        }
                        KeyCode::Char('n') => {
                            if let Some(_) = &app.search_regex {
                                if !app.search_matches.is_empty() {
                                    app.search_idx=(app.search_idx+1)%app.search_matches.len();
                                    app.selected_path=app.search_matches[app.search_idx].clone();
                                    let depth=app.selected_path.len();
                                    let h=terminal.size().unwrap().height as usize;
                                    let visible=h.saturating_sub(7);
                                    if depth < app.flame_scroll { app.flame_scroll=depth; }
                                    else if depth >= app.flame_scroll+visible { app.flame_scroll=depth - visible +1; }
                                }
                            }
                        }
                        KeyCode::Char('N') => {
                            if let Some(_) = &app.search_regex {
                                if !app.search_matches.is_empty() {
                                    if app.search_idx==0 { app.search_idx=app.search_matches.len()-1; } else { app.search_idx-=1; }
                                    app.selected_path=app.search_matches[app.search_idx].clone();
                                    let depth=app.selected_path.len();
                                    let h=terminal.size().unwrap().height as usize;
                                    let visible=h.saturating_sub(7);
                                    if depth < app.flame_scroll { app.flame_scroll=depth; }
                                    else if depth >= app.flame_scroll+visible { app.flame_scroll=depth - visible +1; }
                                }
                            }
                        }
                        KeyCode::Char('r') => {
                            app.selected_path=Vec::new();
                            app.zoom_path=None;
                            app.flame_scroll=0;
                            app.search_regex=None;
                            app.search_regex_str.clear();
                            app.search_matches.clear();
                            app.search_idx=0;
                            app.top_filter=None;
                            app.top_filter_str.clear();
                            app.top_selected=0;
                            app.top_scroll=0;
                            app.info_msg=None;
                            update_top_entries(&mut app);
                            app.view=View::Flame;
                        }
                        KeyCode::Tab => {
                            app.view= if app.view==View::Flame {View::Top} else {View::Flame};
                            if app.view==View::Top { update_top_entries(&mut app); }
                        }
                        KeyCode::Char('1') => {
                            if app.view==View::Top { app.top_sort=TopSort::Total; update_top_entries(&mut app); }
                        }
                        KeyCode::Char('2') => {
                            if app.view==View::Top { app.top_sort=TopSort::Own; update_top_entries(&mut app); }
                        }
                        _=>{}
                    }
                }
            }
        }
    }
    disable_raw_mode().unwrap();
    execute!(terminal.backend_mut(), LeaveAlternateScreen).unwrap();
    terminal.show_cursor().unwrap();
    if app.echo {
        let mut out=io::stdout();
        if app.raw.is_empty() { writeln!(out).unwrap(); } else { write!(out,"{}",app.raw).unwrap(); writeln!(out).unwrap(); }
        let _=out.flush();
    }
    Ok(())
}
RS
"}

actions.command:
rm src/main.rs
cat > src/main.rs <<'RS'
use clap::{Arg, Command};
use crossterm::{
    event::{self, Event, KeyCode, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    layout::{Constraint, Direction, Layout},
    prelude::*,
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::Paragraph,
};
use regex::Regex;
use std::{
    collections::{HashMap, HashSet},
    io::{self, IsTerminal, Read, Write},
    time::{Duration, Instant},
};

#[derive(Debug, Clone)]
struct Node {
    name: String,
    total: u64,
    own: u64,
    children: Vec<Node>,
}
impl Node {
    fn new(name: String) -> Self { Self { name, total: 0, own: 0, children: Vec::new() } }
    fn sort_by_total(&mut self) {
        self.children.sort_by(|a,b| b.total.cmp(&a.total));
        for c in &mut self.children { c.sort_by_total(); }
    }
}

#[derive(Clone, Copy, PartialEq)]
enum View { Flame, Top }
#[derive(Clone, Copy, PartialEq)]
enum TopSort { Total, Own }

struct App {
    raw: String,
    root: Node,
    total: u64,
    display_name: String,
    debug: bool,
    echo: bool,
    view: View,
    selected_path: Vec<usize>,
    zoom_path: Option<Vec<usize>>,
    flame_scroll: usize,
    top_selected: usize,
    top_scroll: usize,
    top_sort: TopSort,
    top_filter: Option<Regex>,
    top_filter_str: String,
    in_search: bool,
    search_input: String,
    search_regex: Option<Regex>,
    search_regex_str: String,
    search_matches: Vec<Vec<usize>>,
    search_idx: usize,
    info_msg: Option<String>,
    build_time: Duration,
    render_time: Duration,
    top_entries: Vec<(String,u64,u64)>,
}

fn get_node_ref<'a>(root: &'a Node, path: &[usize]) -> &'a Node {
    let mut n = root;
    for &i in path { n = &n.children[i]; }
    n
}

impl App {
    fn get_node(&self, path: &[usize]) -> &Node { get_node_ref(&self.root, path) }
    fn selected_node(&self) -> &Node { self.get_node(&self.selected_path) }
    fn zoom_node(&self) -> &Node {
        if let Some(p)=&self.zoom_path { self.get_node(p) } else { &self.root }
    }
}

fn build_tree(raw: &str, sorted: bool) -> (Node, u64, Duration) {
    let start = Instant::now();
    let mut root = Node::new("all".to_string());
    let mut total_all = 0u64;
    for line in raw.lines() {
        if line.is_empty() { continue; }
        if let Some(idx) = line.rfind(' ') {
            let stack_part = &line[..idx];
            let count_part = &line[idx+1..];
            if count_part.is_empty() { continue; }
            let count_str = if count_part.starts_with('+') { &count_part[1..] } else if count_part.starts_with('-') { continue; } else { count_part };
            if count_str.is_empty() || !count_str.chars().all(|c| c.is_ascii_digit()) { continue; }
            let count: u64 = match count_str.parse() { Ok(v)=>v, Err(_)=>continue };
            let frames: Vec<String> = stack_part.split(';').map(|s| s.to_string()).collect();
            total_all += count;
            root.total += count;
            let mut cur = &mut root;
            for (i, fr) in frames.iter().enumerate() {
                let pos = cur.children.iter().position(|c| &c.name == fr);
                let idx2 = if let Some(p)=pos { p } else { cur.children.push(Node::new(fr.clone())); cur.children.len()-1 };
                cur = &mut cur.children[idx2];
                cur.total += count;
                if i==frames.len()-1 { cur.own += count; }
            }
        }
    }
    if sorted { root.sort_by_total(); }
    (root, total_all, start.elapsed())
}

fn update_top_entries(app: &mut App) {
    let mut map: HashMap<String,(u64,u64)> = HashMap::new();
    for line in app.raw.lines() {
        if line.is_empty() { continue; }
        if let Some(idx)=line.rfind(' ') {
            let stack_part=&line[..idx];
            let count_part=&line[idx+1..];
            if count_part.is_empty() { continue; }
            let count_str = if count_part.starts_with('+') { &count_part[1..] } else if count_part.starts_with('-') { continue; } else { count_part };
            if count_str.is_empty() || !count_str.chars().all(|c| c.is_ascii_digit()) { continue; }
            let count: u64 = match count_str.parse() { Ok(v)=>v, Err(_)=>continue };
            let frames: Vec<String> = stack_part.split(';').map(|s| s.to_string()).collect();
            let mut seen: HashSet<String> = HashSet::new();
            for f in &frames {
                if seen.insert(f.clone()) {
                    let e = map.entry(f.clone()).or_insert((0,0));
                    e.0 += count;
                }
            }
            if let Some(leaf)=frames.last() {
                let e = map.entry(leaf.clone()).or_insert((0,0));
                e.1 += count;
            }
        }
    }
    let mut entries: Vec<(String,u64,u64)> = map.into_iter().map(|(k,(t,o))| (k,t,o)).collect();
    // apply filter
    if app.view == View::Top {
        if let Some(re)=&app.top_filter {
            entries.retain(|(n,_,_)| re.is_match(n));
        } else if let Some(re)=&app.search_regex {
            entries.retain(|(n,_,_)| re.is_match(n));
        }
    }
    match app.top_sort {
        TopSort::Total => entries.sort_by(|a,b| b.1.cmp(&a.1).then(b.2.cmp(&a.2))),
        TopSort::Own => entries.sort_by(|a,b| b.2.cmp(&a.2).then(b.1.cmp(&a.1))),
    }
    app.top_entries = entries;
    if app.top_entries.is_empty() { app.top_selected=0; app.top_scroll=0; }
    else if app.top_selected >= app.top_entries.len() { app.top_selected = app.top_entries.len()-1; }
}

fn collect_matches(root: &Node, re: &Regex) -> Vec<Vec<usize>> {
    let mut out=Vec::new();
    fn dfs(node: &Node, path: Vec<usize>, re: &Regex, out: &mut Vec<Vec<usize>>) {
        if re.is_match(&node.name) { out.push(path.clone()); }
        for (i, child) in node.children.iter().enumerate() {
            let mut np=path.clone(); np.push(i);
            dfs(child, np, re, out);
        }
    }
    dfs(root, Vec::new(), re, &mut out);
    out
}

fn color_for(name: &str) -> Color {
    if name=="all" { return Color::Rgb(250,250,250); }
    let mut h:u32=0;
    for b in name.bytes(){ h=h.wrapping_mul(31).wrapping_add(b as u32); }
    let palette = [
        Color::Rgb(227,102,24),
        Color::Rgb(216,52,12),
        Color::Rgb(208,13,3),
        Color::Rgb(205,3,0),
        Color::Rgb(248,200,47),
        Color::Rgb(246,191,45),
        Color::Rgb(209,21,5),
        Color::Rgb(232,120,30),
        Color::Rgb(237,140,40),
    ];
    palette[(h as usize)%palette.len()]
}

fn build_rows(root: &Node, width: usize, zoom_path: &Option<Vec<usize>>) -> Vec<Vec<(String,usize,usize,Vec<usize>,u64)>> {
    let mut rows: Vec<Vec<(String,usize,usize,Vec<usize>,u64)>> = Vec::new();
    if let Some(zp)=zoom_path {
        let zd=zp.len();
        for d in 0..=zd {
            let path=zp[0..d].to_vec();
            let node=get_node_ref(root,&path);
            if rows.len()<=d { rows.push(Vec::new()); }
            rows[d].push((node.name.clone(),0,width,path.clone(),node.total));
        }
        let zn=get_node_ref(root, zp);
        fn rec(node:&Node,x0:usize,x1:usize,depth:usize,rows:&mut Vec<Vec<(String,usize,usize,Vec<usize>,u64)>>,cur_path:Vec<usize>){
            if node.children.is_empty(){return;}
            let pw=x1-x0;
            if node.total==0||pw==0 {return;}
            let mut cur=x0;
            for (i,child) in node.children.iter().enumerate(){
                let mut np=cur_path.clone(); np.push(i);
                let cw= if i==node.children.len()-1 {x1-cur} else {
                    let w=(child.total as f64/node.total as f64*pw as f64).round() as usize;
                    let w=if child.total>0&&w==0 {1} else {w};
                    std::cmp::min(w,x1-cur)
                };
                let cd=depth+1;
                if rows.len()<=cd {rows.resize(cd+1,Vec::new());}
                rows[cd].push((child.name.clone(),cur,cw,np.clone(),child.total));
                rec(child,cur,cur+cw,cd,rows,np);
                cur+=cw;
            }
        }
        rec(zn,0,width,zd,&mut rows,zp.clone());
    } else {
        fn rec2(node:&Node,x0:usize,x1:usize,depth:usize,rows:&mut Vec<Vec<(String,usize,usize,Vec<usize>,u64)>>,cur_path:Vec<usize>){
            if rows.len()<=depth {rows.resize(depth+1,Vec::new());}
            rows[depth].push((node.name.clone(),x0,x1-x0,cur_path.clone(),node.total));
            if node.children.is_empty(){return;}
            let pw=x1-x0;
            if node.total==0||pw==0 {return;}
            let mut cur=x0;
            for (i,child) in node.children.iter().enumerate(){
                let mut np=cur_path.clone(); np.push(i);
                let cw= if i==node.children.len()-1 {x1-cur} else {
                    let w=(child.total as f64/node.total as f64*pw as f64).round() as usize;
                    let w=if child.total>0&&w==0 {1} else {w};
                    std::cmp::min(w,x1-cur)
                };
                rec2(child,cur,cur+cw,depth+1,rows,np);
                cur+=cw;
            }
        }
        rec2(root,0,width,0,&mut rows, Vec::new());
    }
    rows
}

fn main() -> io::Result<()> {
    let cmd = Command::new("flamelens").version("0.3.1").about("")
        .arg(Arg::new("FILENAME").help("Profile data filename").required(false))
        .arg(Arg::new("sorted").long("sorted").help("Whether to sort the stacks by time spent").action(clap::ArgAction::SetTrue))
        .arg(Arg::new("echo").long("echo").help("Print data to stdout on exit. Useful when piping to other tools").action(clap::ArgAction::SetTrue))
        .arg(Arg::new("debug").long("debug").help("Show debug info").action(clap::ArgAction::SetTrue));
    let matches = cmd.get_matches();
    let filename: Option<String> = matches.get_one::<String>("FILENAME").cloned();
    let sorted = matches.get_flag("sorted");
    let echo = matches.get_flag("echo");
    let debug = matches.get_flag("debug");

    let (raw, display_name) = if let Some(fname)=filename {
        let data = std::fs::read_to_string(&fname).unwrap_or_else(|e| panic!("Could not read file: {:?}", e));
        (data, fname)
    } else {
        let mut s = String::new();
        if io::stdin().is_terminal() {
            (String::new(), "stdin".to_string())
        } else {
            let _ = io::stdin().read_to_string(&mut s);
            (s, "stdin".to_string())
        }
    };
    let (root,total,build_time)=build_tree(&raw, sorted);
    let mut app = App {
        raw: raw.clone(),
        root,
        total,
        display_name,
        debug,
        echo,
        view: View::Flame,
        selected_path: Vec::new(),
        zoom_path: None,
        flame_scroll: 0,
        top_selected: 0,
        top_scroll: 0,
        top_sort: TopSort::Own,
        top_filter: None,
        top_filter_str: String::new(),
        in_search: false,
        search_input: String::new(),
        search_regex: None,
        search_regex_str: String::new(),
        search_matches: Vec::new(),
        search_idx: 0,
        info_msg: None,
        build_time,
        render_time: Duration::from_millis(0),
        top_entries: Vec::new(),
    };
    update_top_entries(&mut app);

    let mut stdout = io::stdout();
    if let Err(_) = enable_raw_mode() {
        eprintln!("Error: Os {{ code: 11, kind: WouldBlock, message: \"Resource temporarily unavailable\" }}");
        if app.echo {
            if app.raw.is_empty() { writeln!(stdout).unwrap(); } else { write!(stdout,"{}",app.raw).unwrap(); writeln!(stdout).unwrap(); }
            let _ = stdout.flush();
        }
        std::process::exit(1);
    }
    execute!(stdout, EnterAlternateScreen).unwrap();
    let backend = ratatui::backend::CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend).unwrap();
    let mut should_quit = false;
    while !should_quit {
